{"implementation": "def solve(case):
    payload = case["payload"]
    nodes = payload["nodes"]
    required_symbols = set(payload["required_symbols"])

    # Validate required fields
    for n in nodes:
        for field in ("id", "parent", "symbol", "depth", "removable", "utility"):
            if field not in n:
                raise ValueError(f"Node missing required field: {field}")
    if "required_symbols" not in payload:
        raise ValueError("payload missing required_symbols")

    node_map = {n["id"]: n for n in nodes}

    # Build children map
    children = {n["id"]: [] for n in nodes}
    for n in nodes:
        if n["parent"] is not None:
            parent_id = n["parent"]
            if parent_id not in children:
                raise ValueError(f"Unknown parent id: {parent_id}")
            children[parent_id].append(n["id"])

    # Sort: deeper nodes first; stable tiebreak by node id ascending
    sorted_nodes = sorted(nodes, key=lambda n: (-n["depth"], n["id"]))

    retained = set(n["id"] for n in nodes)
    removal_order = []

    for node in sorted_nodes:
        nid = node["id"]

        # Only removable nodes are candidates
        if not node["removable"]:
            continue

        # Skip if any children are still retained
        if any(c in retained for c in children[nid]):
            continue

        # Tentatively remove
        retained.discard(nid)

        # Check all required symbols still represented
        retained_symbols = {node_map[rid]["symbol"] for rid in retained}
        if required_symbols.issubset(retained_symbols):
            removal_order.append(nid)
        else:
            # Restore — removal would violate required symbol coverage
            retained.add(nid)

    return {
        "retained_ids": sorted(retained),
        "removal_order": removal_order
    }
"}
